// Verified expansion sourced selectively from USDA SR28 / FoodData Central SR Legacy.
// Values are retained only where the source provides the core profile required by
// the existing 3T.13 model. Missing source nutrients remain absent.

import type { Micronutrients } from '@/types/nutrition';
import type { SystemFoodDef } from './system-foods';

const USDA_SR28 = 'USDA FoodData Central, SR Legacy / SR28 (May 2016), per 100 g edible portion';

function g100(
  id: string,
  name: string,
  category: string,
  preparation: SystemFoodDef['preparation'],
  sourceDetail: string,
  n: {
    calories: number; protein: number; carbohydrates: number; fat: number;
    fiber: number; sugar: number; saturatedFat: number; sodium: number;
    micronutrients?: Micronutrients;
    monounsaturatedFat?: number;
    polyunsaturatedFat?: number;
    transFat?: number;
  },
  description?: string,
  quantityConversions?: SystemFoodDef['quantityConversions'],
  aliases?: string[],
): SystemFoodDef {
  return {
    id, name,
    ...(aliases ? { aliases } : {}),
    category, preparation, source: 'system', sourceDetail,
    description: description ?? null, brand: null,
    serving: { amount: 100, unit: 'g' },
    nutrition: {
      basis: 'per_100g', servingAmount: null, servingUnit: null,
      calories: n.calories, protein: n.protein, carbohydrates: n.carbohydrates, fat: n.fat,
      fiber: n.fiber, sugar: n.sugar, saturatedFat: n.saturatedFat, sodium: n.sodium,
      ...(n.monounsaturatedFat !== undefined ? { monounsaturatedFat: n.monounsaturatedFat } : {}),
      ...(n.polyunsaturatedFat !== undefined ? { polyunsaturatedFat: n.polyunsaturatedFat } : {}),
      ...(n.transFat !== undefined ? { transFat: n.transFat } : {}),
      micronutrients: n.micronutrients ?? {},
    },
    ...(quantityConversions ? { quantityConversions } : {}),
  };
}

